3.1 Conditional Statements (if, else, switch)
int number = 10;
if (number > 5) {
    Console.WriteLine("The number is greater than 5.");
}

items.body:
if-else Statement
if-else statement ត្រូូវបានប្រើដើម្បីីប្រតិបត្តិិកូដផ្សេងៗដោយផ្អែកលើលក្ខណ្ឌ។ ប្រសិនបើលក្ខណ្ឌគឺពិត
(`true`), កូដនៅក្នុង if block នឹងត្រូូវបានអនុវត្ត។ បើមិនដូច្នេះទេ, កូដនៅក្នុង else block នឹងត្រូូវបាន
អនុវត្ត។
int age = 18;
if (age >= 18) {
    Console.WriteLine("You are an adult.");
} else {
    Console.WriteLine("You are a minor.");
}
លទ្ធផល៖
You are an adult.
if-else if-else Statement
if-else if-else statement ត្រូូវបានប្រើដើម្បីីពិនិត្យលក្ខណ្ឌច្រើន។ ប្រសិនបើលក្ខណ្ឌទីមួយមិនពិត
(`false`), លក្ខណ្ឌបន្ទាប់នឹងត្រូូវបានពិនិត្យ។ ប្រសិនបើគ្មានលក្ខណ្ឌណាមួយពិតទេ, កូដនៅក្នុង else block
នឹងត្រូូវបានអនុវត្ត។
int score = 85;
if (score >= 90) {
    Console.WriteLine("Grade: A");
} else if (score >= 80) {
    Console.WriteLine("Grade: B");
} else if (score >= 70) {
    Console.WriteLine("Grade: C");
} else {
    Console.WriteLine("Grade: F");
}
លទ្ធផល៖
Grade: B
