4.4 Recursion
Recursion គឺជាការហៅ method ដោយខ្លួនឯង។ វាមានប្រយោជន៍សម្
រាប់ការដោះស្
រាយបញ្ហាដូចជា
factorial ឬ Fibonacci។
ឧទាហរណ៍នៃ recursion៖
int Factorial(int n) {
    if (n == 0) {
        return 1;
    }
    return n * Factorial(n - 1);
}
int result = Factorial(5);
Console.WriteLine(result);
លទ្ធផល៖
120
ឧទាហរណ៍នៃ Fibonacci sequence៖
int Fibonacci(int n) {
    if (n <= 1) {
        return n;
    }
    return Fibonacci(n - 1) + Fibonacci(n - 2);
}
int result = Fibonacci(6);
Console.WriteLine(result);

